INSERT INTO audit_entries (action,entityType,entityId,summary,metadata) SELECT 'provider.api_catalogue.publish','provider',CAST(p.id AS CHAR),'Owner requested publication of the connected JustAnotherPanel source catalogue',JSON_OBJECT('mode','api_source','previousStatus',p.status,'qualityVerified',false,'serviceReviewsUnchanged',true) FROM provider_records p WHERE p.slug='justanotherpanel' AND p.status <> 'suspended' AND p.apiCataloguePublished=false AND EXISTS (SELECT 1 FROM provider_integrations i WHERE i.providerId=p.id AND i.baseUrl='https://justanotherpanel.com/api/v2' AND i.status='active' AND i.lastSyncedAt IS NOT NULL AND i.credentialCiphertext IS NOT NULL);
