UPDATE provider_records p SET p.status='active',p.apiCataloguePublished=true WHERE p.slug='justanotherpanel' AND p.status <> 'suspended' AND EXISTS (SELECT 1 FROM provider_integrations i WHERE i.providerId=p.id AND i.baseUrl='https://justanotherpanel.com/api/v2' AND i.status='active' AND i.lastSyncedAt IS NOT NULL AND i.credentialCiphertext IS NOT NULL);
